import numpy as np
from scipy.special import erfc

 # inverse CDF, exponential
def inv_cdf_exponential(u, lam):

    if lam <= 0:
        raise ValueError("lam must be positive")

    u = np.asarray(u, dtype=float)
    if np.any((u < 0) | (u >= 1)):
        raise ValueError("u must satisfy 0 <= u < 1")

    # log1p(-u) is more accurate than log(1-u) 
    return -np.log1p(-u) / lam

   

# inverse CDF, Rayleigh
def inv_cdf_rayleigh(u, sigma):
    """Return Rayleigh samples generated by inverse-CDF sampling"""
    if sigma <= 0:
        raise ValueError("sigma must be positive")

    u = np.asarray(u, dtype=float)
    if np.any((u < 0) | (u >= 1)):
        raise ValueError("u must satisfy 0 <= u < 1")

    return sigma * np.sqrt(-2.0 * np.log1p(-u))

# uniform in, samples out

def sample_by_inversion(inv_cdf, n, rng, **kw):
    """Generate n samples using an inverse CDF and a NumPy Generator"""
    if n < 0:
        raise ValueError("n must be nonnegative")

    u = rng.random(n)
    return inv_cdf(u, **kw)

# sup |empirical CDF - analytic CDF|

def ks_statistic(samples, cdf):
    """Return sup |empirical CDF - analytic CDF| for one sample set"""
    samples = np.sort(np.asarray(samples, dtype=float))
    n = samples.size

    if n == 0:
        raise ValueError("samples must not be empty")

    analytic = np.asarray(cdf(samples), dtype=float)
    if analytic.shape != samples.shape:
        raise ValueError("cdf must return one value for each sample")
    # The empirical CDF jumps at each sorted sample
    upper = np.arange(1, n + 1) / n
    lower = np.arange(0, n) / n

    return float(max(np.max(upper - analytic),
                     np.max(analytic - lower)))

# the Gaussian tail probability
def q_function(x):
    """Return the Gaussian upper-tail probability Q(x)
    Q(x) = 0.5 * erfc(x / sqrt(2))
    """
    x = np.asarray(x, dtype=float)
    return 0.5 * erfc(x / np.sqrt(2.0))